# Better approach: scan for corners and grow rectangles
def find_rectangles_v2(grid):
    rects = []
    visited = set()

    for r in range(rows):
        for c in range(cols):
            if (r, c) in visited or grid[r][c] == 6:
                continue

            color = grid[r][c]

            # This could be a corner. Check all orientations
            for top_r in range(max(0, r-3), min(rows, r+1)):
                for left_c in range(max(0, c-3), min(cols, c+1)):
                    if grid[top_r][left_c] != color:
                        continue
                    if top_r == r and left_c == c:
                        for ht in range(4, min(rows - top_r + 1, 10)):
                            for wd in range(4, min(cols - left_c + 1, 10)):
                                if all(
                                    grid[top_r + cr][left_c + cc] == color 
                                    or grid[top_r + ht - 1 - cr][left_c + cc] == color
                                    or grid[top_r + cr][left_c + wd - 1 - cc] == color
                                    or grid[top_r + ht - 1 - cr][left_c + wd - 1 - cc] == color
                                    for cr in range(ht) for cc in range(wd)
                                ) and interior_clear = all(
                                    grid[top_r + cr][left_c + cc] != color
                                    for cr in range(1, ht - 1) for cc in range(1, wd - 1)
                                ):
                                    rects.append({'color': color, 'top': top_r, 'left': left_c, 'height': ht, 'width': wd})
                                    for rr in range(top_r, top_r + ht):
                                        for cc in range(left_c, left_c + wd):
                                            visited.add((rr, cc))
                                    break
                    if top_r == r:
                        break

            if (r, c) in visited:
                continue

    # Simple scan - find rectangles by checking each color region
    rects = []
    for color in [x for x in range(1, 10) if color != 6]:
        # Find all positions of this color
        positions = [(r, c) for r in range(rows) for c in range(cols) if grid[r][c] == color]

        # Check if it's a single hollow rectangle
        min_r = min(p[0] for p in positions)
        max_r = max(p[0] for p in positions)
        min_c = min(p[1] for p in positions)
        max_c = max(p[1] for p in positions)

        height = max_r - min_r + 1
        width = max_c - min_c + 1

        # Count boundary cells vs actual cells of this color in bounding box
        boundary_cells = [(r, c) for r in range(min_r, max_r + 1) for c in range(min_c, max_c + 1) 
                         if r in [min_r, max_r] or c in [min_c, max_c]]

        actual = sum(1 for p in positions if min_r <= p[0] <= max_r and min_c <= p[1] <= max_c)

        if actual == len(boundary_cells) and actual >= 4:
            rects.append({'color': color, 'top': min_r, 'left': min_c, 'height': height, 'width': width})

    return rects

